mapper.select:
select distinct su.id, su.username, su.phone, su.account, su.create_time, su.status, ( SELECT GROUP_CONCAT( sd.dept_name ) FROM sys_user_job s1, sys_dept sd WHERE s1.user_id = su.id AND s1.deleted = 0 AND s1.dept_id = sd.id AND sd.deleted = 0 ) as `deptName` from sys_user su where su.deleted = 0
and su.status = #{params.status}
and su.username like concat('%',#{params.username},'%')
and su.phone = #{params.phone}
and su.create_time >= #{params.beginTime}
and su.create_time <= #{params.endTime}
and su.id in (select distinct suj.user_id from sys_user_job suj where suj.dept_id = #{params.deptId} and suj.deleted = 0)
order by su.id desc
